function BalanceActions() {
  return (
    <div>
      <h3>Balance Actions</h3>
      <div>
        <form>
          <label htmlFor="amount">Amount:</label>
          <input type="number" id="amount" name="amount" />
        </form>
        <button>Deposit</button>
        <button>Withdraw</button>
      </div>
    </div>
  );
}

export default BalanceActions;
